#![allow(clippy::excessive_precision)]

use thermopack_rs::excess_gibbs::MixingRule;
use thermopack_rs::wong_sandler::{Fraction, WongSandlerData};
use thermopack_rs::{Cubic, CubicKind, CubicOptions};

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-10;

fn kind(name: &str) -> CubicKind {
    match name {
        "PR" => CubicKind::PengRobinson,
        "SRK" => CubicKind::SoaveRedlichKwong,
        "RK" => CubicKind::RedlichKwong,
        "VDW" => CubicKind::VanDerWaals,
        other => panic!("unknown equation of state {other}"),
    }
}

#[test]
fn the_coefficients_match_the_source() {
    let mut rows = include_str!("fixtures/wong_sandler.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(
        header,
        "case;a;a_t;a_tt;a_i_1;a_i_2;a_it_1;a_it_2;b;b_t;b_tt;b_i_1;b_i_2;b_it_1;b_it_2"
    );
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        assert_eq!(fields.len(), 15, "row {row}");
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 7, "case {row}");
        let components: Vec<&str> = case[1].split(',').collect();
        let temperature: f64 = case[2].parse().expect("the temperature");
        let composition: Vec<f64> = case[3]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let kij: f64 = case[4].parse().expect("the binary interaction parameter");
        let tauij: f64 = case[5]
            .parse()
            .expect("the parameter of the second order term");
        let alpha: f64 = case[6]
            .parse()
            .expect("the exponent of the second order term");

        let mut data = WongSandlerData::new(components.len());
        data.set_kij(0, 1, Fraction::constant(kij))
            .expect("the parameter");
        data.set_kij(1, 0, Fraction::constant(kij))
            .expect("the parameter");
        data.set_tauij(0, 1, Fraction::constant(tauij))
            .expect("the parameter");
        data.set_tauij(1, 0, Fraction::constant(tauij))
            .expect("the parameter");
        data.set_alphaij(0, 1, alpha).expect("the exponent");
        data.set_alphaij(1, 0, alpha).expect("the exponent");
        let options = CubicOptions {
            mixing_rule: MixingRule::WongSandler,
            wong_sandler: Some(&data),
            ..Default::default()
        };
        let model = Cubic::with_options(kind(case[0]), &components, options).expect("the model");
        let coefficients = model
            .wong_sandler_coefficients(temperature, &composition)
            .expect("the coefficients");
        let native = [
            coefficients.a,
            coefficients.a_t,
            coefficients.a_tt,
            coefficients.a_i[0],
            coefficients.a_i[1],
            coefficients.a_it[0],
            coefficients.a_it[1],
            coefficients.b,
            coefficients.b_t,
            coefficients.b_tt,
            coefficients.b_i[0],
            coefficients.b_i[1],
            coefficients.b_it[0],
            coefficients.b_it[1],
        ];
        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn the_parameters_need_the_matching_mixing_rule() {
    let data = WongSandlerData::new(2);
    let options = CubicOptions {
        mixing_rule: MixingRule::VdW,
        wong_sandler: Some(&data),
        ..Default::default()
    };
    assert!(Cubic::with_options(CubicKind::PengRobinson, &["CO2", "NC4"], options).is_err());
}

#[test]
fn the_model_without_parameters_is_rejected() {
    let options = CubicOptions {
        mixing_rule: MixingRule::WongSandler,
        ..Default::default()
    };
    let model = Cubic::with_options(CubicKind::PengRobinson, &["CO2", "NC4"], options)
        .expect("the model of the case");
    assert!(model.wong_sandler_coefficients(300.0, &[0.5, 0.5]).is_err());
}
